1	<!DOCTYPE html>
2	<html lang="en">
3	<head>
4	    <meta charset="UTF-8">
5	    <meta name="viewport" content="width=device-width, initial-scale=1.0">
6	    <title>Conductor</title>
7	    <link rel="stylesheet" href="styles/base.css">
8	    <style>
9	        body { display: flex; flex-direction: column; }
10	
11	        /* Top nav shell */
12	        .topnav {
13	            display: flex; align-items: center; gap: 4px; padding: 0 20px;
14	            background: linear-gradient(180deg, #0d161f 0%, #0a1219 100%);
15	            border-bottom: 1px solid var(--border-light);
16	            height: 56px; position: sticky; top: 0; z-index: 100;
17	        }
18	        .topnav-brand {
19	            display: flex; align-items: center; gap: 10px;
20	            margin-right: 24px; white-space: nowrap; cursor: pointer;
21	        }
22	        .topnav-mark {
23	            width: 30px; height: 30px;
24	            border-radius: 8px;
25	            background: linear-gradient(135deg, var(--accent-blue), var(--accent-purple));
26	            display: flex; align-items: center; justify-content: center;
27	            font-size: 14px; font-weight: 800; color: #fff;
28	            box-shadow: 0 0 16px rgba(56,189,248,0.3);
29	        }
30	        .topnav-brand-text { display: flex; flex-direction: column; line-height: 1.15; }
31	        .topnav-brand-name {
32	            font-size: 13px; font-weight: 700; color: #fff; letter-spacing: 0.3px;
33	        }
34	        .topnav-brand-sub {
35	            font-size: 9.5px; color: var(--text-dim);
36	            text-transform: uppercase; letter-spacing: 0.14em;
37	        }
38	
39	        .topnav-links {
40	            display: flex; align-items: center; gap: 2px; flex: 1; height: 100%;
41	        }
42	        .topnav-link {
43	            display: flex; align-items: center; gap: 6px;
44	            padding: 0 14px; height: 100%;
45	            font-size: 0.78rem; font-weight: 600;
46	            color: var(--text-secondary); text-decoration: none;
47	            border-bottom: 2px solid transparent;
48	            transition: color 0.2s, border-color 0.2s, background 0.2s;
49	            cursor: pointer; white-space: nowrap;
50	        }
51	        .topnav-link svg {
52	            width: 14px; height: 14px;
53	            stroke: currentColor; fill: none;
54	            stroke-width: 1.8;
55	            stroke-linecap: round; stroke-linejoin: round;
56	        }
57	        .topnav-link:hover { color: #fff; background: rgba(255,255,255,0.03); }
58	        .topnav-link.active {
59	            color: var(--accent-blue);
60	            border-bottom-color: var(--accent-blue);
61	        }
62	
63	        /* Status bar */
64	        .statusbar {
65	            display: flex; align-items: center; gap: 14px;
66	            margin-left: auto; font-size: 0.72rem; flex-shrink: 0;
67	        }
68	        .statusbar-item {
69	            display: flex; align-items: center; gap: 5px;
70	            color: var(--text-dim); white-space: nowrap;
71	        }
72	        .statusbar-val {
73	            font-family: var(--font-mono);
74	            font-weight: 700;
75	            color: var(--text-secondary);
76	        }
77	        .conn-dot {
78	            width: 7px; height: 7px; border-radius: 50%;
79	            display: inline-block;
80	        }
81	        .conn-dot.connected {
82	            background: var(--accent-green);
83	            box-shadow: 0 0 0 0 rgba(74,222,128,0.6);
84	            animation: connPulse 2.2s ease-out infinite;
85	        }
86	        .conn-dot.disconnected {
87	            background: var(--accent-red);
88	            animation: none;
89	        }
90	        @keyframes connPulse {
91	            0%   { box-shadow: 0 0 0 0 rgba(74,222,128,0.5); }
92	            70%  { box-shadow: 0 0 0 8px rgba(74,222,128,0); }
93	            100% { box-shadow: 0 0 0 0 rgba(74,222,128,0); }
94	        }
95	
96	        /* Breadcrumbs */
97	        .breadcrumb-bar {
98	            display: flex; align-items: center; gap: 6px;
99	            padding: 6px 24px; background: rgba(255,255,255,0.015);
100	            border-bottom: 1px solid var(--border-subtle);
101	            font-size: 0.72rem; color: var(--text-dim); min-height: 28px;
102	        }
103	        .breadcrumb-bar a { color: var(--accent-blue); text-decoration: none; cursor: pointer; }
104	        .breadcrumb-bar a:hover { text-decoration: underline; }
105	        .breadcrumb-sep { margin: 0 2px; }
106	
107	        /* Content area */
108	        .content-area {
109	            flex: 1; overflow-y: auto; position: relative;
110	            min-height: calc(100vh - 84px);
111	        }
112	
113	        /* Loading indicator */
114	        .loading-bar {
115	            position: absolute; top: 0; left: 0; right: 0; height: 2px;
116	            background: linear-gradient(90deg, var(--accent-blue), var(--accent-green));
117	            transform: scaleX(0); transform-origin: left;
118	            transition: transform 0.3s; z-index: 10;
119	        }
120	        .loading-bar.active { transform: scaleX(0.7); transition: transform 0.8s; }
121	        .loading-bar.done   { transform: scaleX(1); transition: transform 0.15s; }
122	    </style>
123	</head>
124	<body>
125	    <div class="topnav">
126	        <div class="topnav-brand" onclick="window.navigateTo('sessions')">
127	            <div class="topnav-mark">C</div>
128	            <div class="topnav-brand-text">
129	                <span class="topnav-brand-name">Conductor</span>
130	                <span class="topnav-brand-sub">Product Orchestrator</span>
131	            </div>
132	        </div>
133	
134	        <div class="topnav-links" id="topnav-links">
135	            <a class="topnav-link" data-route="labs">
136	                <svg viewBox="0 0 24 24"><path d="M12 2L2 7l10 5 10-5-10-5z"/><path d="M2 17l10 5 10-5"/><path d="M2 12l10 5 10-5"/></svg>
137	                Labs Institute
138	            </a>
139	            <a class="topnav-link" data-route="groovenet">
140	                <svg viewBox="0 0 24 24"><circle cx="12" cy="12" r="10" fill="none"/><path d="M9 9a3 3 0 106 0"/><path d="M15 15a3 3 0 10-6 0"/><circle cx="12" cy="12" r="2" fill="currentColor"/></svg>
141	                GrooveNet
142	            </a>
143	            <a class="topnav-link" data-route="build-studio">
144	                <svg viewBox="0 0 24 24"><rect x="3" y="3" width="18" height="18" rx="2"/><line x1="3" y1="9" x2="21" y2="9"/><line x1="9" y1="9" x2="9" y2="21"/></svg>
145	                Build Studio
146	            </a>
147	            <a class="topnav-link" data-route="onboarding">
148	                <svg viewBox="0 0 24 24"><path d="M16 21v-2a4 4 0 0 0-4-4H5a4 4 0 0 0-4 4v2"/><circle cx="8.5" cy="7" r="4"/><line x1="20" y1="8" x2="20" y2="14"/><line x1="23" y1="11" x2="17" y2="11"/></svg>
149	                Onboarding
150	            </a>
151	            <a class="topnav-link" data-route="conductor">
152	                <svg viewBox="0 0 24 24"><circle cx="5" cy="12" r="2" fill="currentColor" opacity="0.6"/><circle cx="12" cy="5" r="2" fill="currentColor" opacity="0.6"/><circle cx="19" cy="12" r="2" fill="currentColor" opacity="0.6"/><circle cx="12" cy="19" r="2" fill="currentColor" opacity="0.6"/><line x1="5" y1="12" x2="12" y2="5" opacity="0.4"/><line x1="12" y1="5" x2="19" y2="12" opacity="0.4"/><line x1="19" y1="12" x2="12" y2="19" opacity="0.4"/><line x1="12" y1="19" x2="5" y2="12" opacity="0.4"/></svg>
153	                Conductor
154	            </a>
155	            <a class="topnav-link" data-route="sessions">
156	                <svg viewBox="0 0 24 24"><rect x="3" y="3" width="7" height="14" rx="1"/><rect x="14" y="3" width="7" height="7" rx="1"/><rect x="14" y="14" width="7" height="7" rx="1"/></svg>
157	                Sessions
158	            </a>
159	            <a class="topnav-link" data-route="pipelines">
160	                <svg viewBox="0 0 24 24"><path d="M12 2v4"/><path d="M12 18v4"/><path d="M4.93 4.93l2.83 2.83"/><path d="M16.24 16.24l2.83 2.83"/><path d="M2 12h4"/><path d="M18 12h4"/></svg>
161	                Pipelines
162	            </a>
163	            <a class="topnav-link" data-route="phases">
164	                <svg viewBox="0 0 24 24"><polyline points="22 12 18 12 15 21 9 3 6 12 2 12"/></svg>
165	                Phases
166	            </a>
167	            <a class="topnav-link" data-route="projects">
168	                <svg viewBox="0 0 24 24"><path d="M3 3h7v7H3z"/><path d="M14 3h7v7h-7z"/><path d="M3 14h7v7H3z"/><path d="M14 14h7v7h-7z"/></svg>
169	                Projects
170	            </a>
171	            <a class="topnav-link" data-route="requirements">
172	                <svg viewBox="0 0 24 24"><path d="M14 2H6a2 2 0 0 0-2 2v16a2 2 0 0 0 2 2h12a2 2 0 0 0 2-2V8z"/><polyline points="14 2 14 8 20 8"/><line x1="16" y1="13" x2="8" y2="13"/><line x1="16" y1="17" x2="8" y2="17"/></svg>
173	                Requirements
174	            </a>
175	            <a class="topnav-link" data-route="bootstrap">
176	                <svg viewBox="0 0 24 24"><path d="M12 2L2 7l10 5 10-5-10-5z"/><path d="M2 17l10 5 10-5"/><path d="M2 12l10 5 10-5"/></svg>
177	                Bootstrap
178	            </a>
179	        </div>
180	
181	        <div class="statusbar">
182	            <div class="statusbar-item">
183	                <span class="conn-dot connected" id="conn-dot"></span>
184	                <span id="conn-label">Connected</span>
185	            </div>
186	            <div class="statusbar-item">
187	                Sessions: <span class="statusbar-val" id="stat-sessions">0</span>
188	            </div>
189	            <div class="statusbar-item">
190	                Cost: <span class="statusbar-val" id="stat-cost">$0.00</span>
191	            </div>
192	        </div>
193	    </div>
194	
195	    <div class="breadcrumb-bar" id="breadcrumbs">
196	        <span>Conductor</span>
197	    </div>
198	
199	    <div class="content-area" id="content-area">
200	        <div class="loading-bar" id="loading-bar"></div>
201	        <div id="page-content"></div>
202	    </div>
203	
204	    <style id="page-styles"></style>
205	
206	    <!-- Data preloader -->
207	    <script>
208	    window.ConductorData = { sessions: null, pipelines: null, projects: null };
209	    (function() {
210	        function tryFetch(url) {
211	            return fetch(url).then(function(r) { return r.ok ? r.json() : null; }).catch(function() { return null; });
212	        }
213	        Promise.all([
214	            tryFetch('data/sessions.json'),
215	            tryFetch('data/pipelines.json'),
216	            tryFetch('data/projects.json')
217	        ]).then(function(results) {
218	            window.ConductorData.sessions = results[0];
219	            window.ConductorData.pipelines = results[1];
220	            window.ConductorData.projects = results[2];
221	            window.dispatchEvent(new CustomEvent('conductor-data-ready'));
222	        });
223	    })();
224	    </script>
225	
226	    <!-- SPA router -->
227	    <script>
228	    (function() {
229	        var routes = {
230	            'labs':            { path: 'pages/labs.html',            label: 'Labs Institute' },
231	            'labs-onboarding': { path: 'pages/labs-onboarding.html', label: 'Labs Onboarding' },
232	            'groovenet':    { path: 'pages/groovenet.html',    label: 'GrooveNet' },
233	            'build-studio': { path: 'pages/build-studio.html', label: 'Build Studio' },
234	            'onboarding':   { path: 'pages/onboarding-studio.html', label: 'Product Onboarding Studio' },
235	            'conductor':    { path: 'pages/conductor.html',    label: 'Conductor Console' },
236	            'sessions':     { path: 'pages/sessions.html',     label: 'Sessions' },
237	            'pipelines':    { path: 'pages/pipelines.html',    label: 'Pipelines' },
238	            'phases':       { path: 'pages/phases.html',       label: 'Phases' },
239	            'projects':     { path: 'pages/projects.html',     label: 'Projects' },
240	            'requirements': { path: 'pages/requirements.html', label: 'Requirements' },
241	            'bootstrap':    { path: 'pages/bootstrap.html',    label: 'Bootstrap Console' }
242	        };
243	
244	        var currentRoute = null;
245	
246	        function updateBreadcrumbs(route) {
247	            var bc = document.getElementById('breadcrumbs');
248	            var info = routes[route];
249	            if (!info) return;
250	            var parts = ['<a onclick="window.navigateTo(\'sessions\')">Conductor</a>'];
251	            if (route !== 'sessions') {
252	                parts.push('<span class="breadcrumb-sep">&#8250;</span>');
253	                parts.push('<span style="color:var(--text-secondary);">' + info.label + '</span>');
254	            } else {
255	                parts.push('<span class="breadcrumb-sep">&#8250;</span>');
256	                parts.push('<span style="color:var(--text-secondary);">Session Board</span>');
257	            }
258	            bc.innerHTML = parts.join('');
259	        }
260	
261	        function updateActiveLink(route) {
262	            document.querySelectorAll('.topnav-link[data-route]').forEach(function(l) {
263	                l.classList.toggle('active', l.dataset.route === route);
264	            });
265	        }
266	
267	        function extractContent(html) {
268	            var styles = '';
269	            var bodyContent = '';
270	
271	            var styleMatches = html.match(/<style[^>]*>([\s\S]*?)<\/style>/gi);
272	            if (styleMatches) {
273	                for (var i = 0; i < styleMatches.length; i++) {
274	                    var inner = styleMatches[i].replace(/<\/?style[^>]*>/gi, '');
275	                    styles += inner + '\n';
276	                }
277	            }
278	
279	            var bodyMatch = html.match(/<body[^>]*>([\s\S]*)<\/body>/i);
280	            if (bodyMatch) {
281	                bodyContent = bodyMatch[1];
282	            }
283	
284	            var scripts = [];
285	            var scriptRe = /<script\b([^>]*)>([\s\S]*?)<\/script>/gi;
286	            var sm;
287	            while ((sm = scriptRe.exec(html)) !== null) {
288	                var attrs = sm[1] || '';
289	                var inline = sm[2] || '';
290	                var srcMatch = attrs.match(/\bsrc\s*=\s*["']([^"']+)["']/i);
291	                if (srcMatch) {
292	                    scripts.push({ src: srcMatch[1] });
293	                } else if (inline.trim()) {
294	                    scripts.push({ code: inline });
295	                }
296	            }
297	            return { styles: styles, body: bodyContent, scripts: scripts };
298	        }
299	
300	        window.navigateTo = function(route) {
301	            if (!routes[route]) return;
302	            if (route === currentRoute) return;
303	            currentRoute = route;
304	
305	            window.location.hash = route;
306	            updateActiveLink(route);
307	            updateBreadcrumbs(route);
308	
309	            var fullscreen = (route === 'labs');
310	            document.querySelector('.topnav').style.display = fullscreen ? 'none' : '';
311	            document.querySelector('.breadcrumb-bar').style.display = fullscreen ? 'none' : '';
312	            document.querySelector('.content-area').style.minHeight = fullscreen ? '100vh' : '';
313	
314	            var pagePath = routes[route].path;
315	            var loadBar = document.getElementById('loading-bar');
316	            var content = document.getElementById('page-content');
317	            var pageStyles = document.getElementById('page-styles');
318	
319	            loadBar.className = 'loading-bar active';
320	
321	            fetch(pagePath)
322	                .then(function(r) {
323	                    if (!r.ok) throw new Error('Page not found');
324	                    return r.text();
325	                })
326	                .then(function(html) {
327	                    var parsed = extractContent(html);
328	                    pageStyles.textContent = parsed.styles;
329	
330	                    // Strip script tags from body content before injecting
331	                    var cleanBody = parsed.body.replace(/<script\b[^>]*>[\s\S]*?<\/script>/gi, '');
332	                    content.innerHTML = cleanBody;
333	
334	                    // Remove old page scripts before adding new ones
335	                    document.querySelectorAll('script[data-page-script]').forEach(function(old) {
336	                        old.remove();
337	                    });
338	
339	                    // Execute scripts in order
340	                    parsed.scripts.forEach(function(s) {
341	                        var el = document.createElement('script');
342	                        el.setAttribute('data-page-script', route);
343	                        if (s.src) {
344	                            el.src = s.src;
345	                        } else {
346	                            el.textContent = s.code;
347	                        }
348	                        document.body.appendChild(el);
349	                    });
350	
351	                    loadBar.className = 'loading-bar done';
352	                    setTimeout(function() { loadBar.className = 'loading-bar'; }, 300);
353	                })
354	                .catch(function(err) {
355	                    content.innerHTML = '<div style="padding:60px 20px;text-align:center;color:var(--text-muted);">' +
356	                        '<h2 style="margin-bottom:8px;">Page not found</h2>' +
357	                        '<p style="font-size:0.85rem;">' + route + ' is not yet available.</p></div>';
358	                    loadBar.className = 'loading-bar';
359	                });
360	        };
361	
362	        // Nav link click handlers
363	        document.querySelectorAll('.topnav-link[data-route]').forEach(function(link) {
364	            link.addEventListener('click', function(e) {
365	                e.preventDefault();
366	                window.navigateTo(this.dataset.route);
367	            });
368	        });
369	
370	        // Boot: route from hash or default to conductor
371	        var hash = window.location.hash.replace('#', '').split('&')[0];
372	        window.navigateTo(hash && routes[hash] ? hash : 'labs');
373	
374	        // Handle back/forward
375	        window.addEventListener('hashchange', function() {
376	            var h = window.location.hash.replace('#', '').split('&')[0];
377	            if (h && routes[h] && h !== currentRoute) {
378	                window.navigateTo(h);
379	            }
380	        });
381	    })();
382	    </script>
383	
384	    <!-- Status bar updater -->
385	    <script>
386	    (function() {
387	        function updateStats() {
388	            var sessions = window.ConductorData.sessions;
389	            if (!sessions || !Array.isArray(sessions)) return;
390	
391	            var running = sessions.filter(function(s) { return s.status === 'running'; }).length;
392	            var total = sessions.length;
393	            var cost = sessions.reduce(function(sum, s) { return sum + (s.cost_usd || 0); }, 0);
394	
395	            var statEl = document.getElementById('stat-sessions');
396	            var costEl = document.getElementById('stat-cost');
397	            if (statEl) statEl.textContent = running + '/' + total;
398	            if (costEl) costEl.textContent = '$' + cost.toFixed(2);
399	        }
400	
401	        window.addEventListener('conductor-data-ready', updateStats);
402	        window.addEventListener('conductor-sessions-updated', updateStats);
403	    })();
404	    </script>
405	</body>
406	</html>
