320	        function formatDuration(sec) {
321	            if (!sec || sec < 0) return '--';
322	            var m = Math.floor(sec / 60);
323	            var s = Math.floor(sec % 60);
324	            return m + ':' + (s < 10 ? '0' : '') + s;
325	        }
