327	        function formatCost(c) {
328	            return '$' + (c || 0).toFixed(2);
329	        }
330	
331	        function truncate(str, len) {
332	            if (!str) return '';
333	            return str.length > len ? str.substring(0, len) + '...' : str;
334	        }
335	
336	        function elapsed(startIso) {
337	            if (!startIso) return 0;
338	            return (Date.now() - new Date(startIso).getTime()) / 1000;
339	        }
340	
341	        function showToast(msg, isError) {
342	            var t = $('toast');
343	            t.textContent = msg;
344	            t.className = 'toast' + (isError ? ' error' : '') + ' show';
345	            setTimeout(function() { t.className = 'toast'; }, 3000);
346	        }
