348	        // --- Kanban rendering ---
349	        function renderBoard() {
350	            var buckets = { queued: [], running: [], complete: [], reviewing: [] };
351	
352	            sessions.forEach(function(s) {
353	                if (s.status === 'queued') buckets.queued.push(s);
354	                else if (s.status === 'running') buckets.running.push(s);
355	                else if (s.status === 'succeeded' || s.status === 'failed') buckets.complete.push(s);
356	                else if (s.status === 'reviewing') buckets.reviewing.push(s);
357	                else buckets.queued.push(s);
358	            });
359	
360	            Object.keys(buckets).forEach(function(key) {
361	                var container = $('col-' + key);
362	                var countEl = $('col-count-' + key);
363	                if (countEl) countEl.textContent = buckets[key].length;
364	
365	                if (buckets[key].length === 0) {
366	                    container.innerHTML = '<div class="kanban-empty">No sessions</div>';
367	                    return;
368	                }
369	
370	                container.innerHTML = buckets[key].map(function(s) {
371	                    var modelClass = (s.model || 'sonnet').toLowerCase();
372	                    var statusClass = 'status-' + (s.status || 'queued');
373	                    var durationStr = '';
374	                    if (s.status === 'running' && s.started_at) {
375	                        durationStr = formatDuration(elapsed(s.started_at));
376	                    } else if (s.duration_seconds) {
377	                        durationStr = formatDuration(s.duration_seconds);
378	                    }
379	
380	                    return '<div class="session-card ' + statusClass + '" onclick="window.openDetail(\'' + s.id + '\')">' +
381	                        '<div class="session-card-row">' +
382	                            '<span class="session-card-id" title="' + s.id + '">' + truncate(s.id, 12) + '</span>' +
383	                            '<span class="session-card-model ' + modelClass + '">' + (s.model || 'sonnet') + '</span>' +
384	                            (s.template ? '<span class="session-card-template">' + s.template + '</span>' : '') +
385	                        '</div>' +
386	                        '<div class="session-card-preview">' + truncate(s.last_output || s.prompt || '', 60) + '</div>' +
387	                        '<div class="session-card-meta">' +
388	                            '<span class="session-card-cost">' + formatCost(s.cost_usd) + '</span>' +
389	                            (durationStr ? '<span class="session-card-duration">' + durationStr + '</span>' : '') +
390	                        '</div>' +
391	                    '</div>';
392	                }).join('');
393	            });
394	
395	            // Update header stats
396	            var running = sessions.filter(function(s) { return s.status === 'running'; }).length;
397	            var cost = sessions.reduce(function(sum, s) { return sum + (s.cost_usd || 0); }, 0);
