406	        // --- Data loading ---
407	        function loadSessions() {
408	            // Try API first, then ConductorData, then static file
409	            fetch('/api/sessions')
410	                .then(function(r) { return r.ok ? r.json() : Promise.reject(); })
411	                .then(function(data) {
412	                    sessions = Array.isArray(data) ? data : (data.sessions || []);
413	                    window.ConductorData.sessions = sessions;
414	                    renderBoard();
415	                    if (selectedId) refreshDetail(selectedId);
416	                })
417	                .catch(function() {
418	                    // Fallback: ConductorData from preloader
419	                    if (window.ConductorData.sessions) {
420	                        sessions = window.ConductorData.sessions;
421	                        renderBoard();
422	                        return;
423	                    }
424	                    // Fallback: static file
425	                    fetch('../data/sessions.json')
426	                        .then(function(r) { return r.ok ? r.json() : []; })
427	                        .then(function(data) {
428	                            sessions = Array.isArray(data) ? data : (data.sessions || []);
