538	            if (!s) return;
539	
540	            var gates = s.quality_gates || {};
541	            var gateKeys = ['compiles', 'tests_pass', 'requirements_met', 'no_security_issues'];
542	
543	            var html = '';
544	            html += '<h2 style="font-size:1.1rem;margin-bottom:4px;">Session Detail</h2>';
545	            html += '<div style="font-family:var(--font-mono);font-size:0.78rem;color:var(--accent-blue);margin-bottom:16px;">' + s.id + '</div>';
546	
547	            // Info section
548	            html += '<div class="detail-section">';
549	            html += '<div class="detail-section-title">Info</div>';
550	            html += '<div class="detail-row"><span class="detail-row-label">Status</span><span class="detail-row-val"><span class="status-dot ' + s.status + '" style="margin-right:4px;"></span>' + s.status + '</span></div>';
551	            html += '<div class="detail-row"><span class="detail-row-label">Model</span><span class="detail-row-val">' + (s.model || 'sonnet') + '</span></div>';
552	            html += '<div class="detail-row"><span class="detail-row-label">Template</span><span class="detail-row-val">' + (s.template || '--') + '</span></div>';
553	            html += '<div class="detail-row"><span class="detail-row-label">Cost</span><span class="detail-row-val">' + formatCost(s.cost_usd) + '</span></div>';
