556	            }
557	            if (s.started_at) {
558	                html += '<div class="detail-row"><span class="detail-row-label">Started</span><span class="detail-row-val">' + new Date(s.started_at).toLocaleString() + '</span></div>';
559	            }
560	            if (s.completed_at) {
561	                html += '<div class="detail-row"><span class="detail-row-label">Completed</span><span class="detail-row-val">' + new Date(s.completed_at).toLocaleString() + '</span></div>';
562	            }
563	            if (s.duration_seconds) {
