565	            }
566	            html += '</div>';
567	
568	            // Output section
569	            html += '<div class="detail-section">';
570	            html += '<div class="detail-section-title">Output</div>';
571	            html += '<div class="detail-output" id="detail-output">Loading output...</div>';
572	            html += '</div>';
573	
574	            // Quality gates
575	            html += '<div class="detail-section">';
576	            html += '<div class="detail-section-title">Quality Gates</div>';
577	            html += '<div class="quality-gates">';
578	            gateKeys.forEach(function(key) {
579	                var checked = gates[key] === true;
580	                var label = key.replace(/_/g, ' ').replace(/\b\w/g, function(l) { return l.toUpperCase(); });
581	                html += '<label class="gate-item' + (checked ? ' checked' : '') + '">' +
582	                    '<input type="checkbox"' + (checked ? ' checked' : '') + ' onchange="window.updateGate(\'' + sessionId + '\', \'' + key + '\', this.checked)">' +
583	                    label +
584	                '</label>';
585	            });
586	            html += '</div></div>';
587	
588	            // Session lineage
589	            if (s.continued_from) {
590	                html += '<div class="detail-section">';
591	                html += '<div class="detail-section-title">Lineage</div>';
592	                html += '<div class="detail-row"><span class="detail-row-label">Continued from</span>';
593	                html += '<span class="detail-row-val" style="cursor:pointer;color:var(--accent-blue);" ';
594	                html += 'onclick="window.openDetail(\'' + s.continued_from + '\')">' + s.continued_from + '</span></div>';
595	                html += '</div>';
596	            }
597	
598	            // Validation results
599	            html += '<div class="detail-section" id="validation-section">';
600	            html += '<div class="detail-section-title" style="display:flex;justify-content:space-between;align-items:center;">Validation';
601	            html += '<button class="btn btn-ghost" style="font-size:0.6rem;padding:2px 8px;" onclick="window.revalidateSession(\'' + sessionId + '\')">Re-validate</button>';
602	            html += '</div>';
603	            html += '<div id="validation-results">Loading...</div>';
604	            html += '</div>';
605	
606	            // Learnings
607	            html += '<div class="detail-section">';
608	            html += '<div class="detail-section-title">Learnings</div>';
609	            html += '<textarea class="form-textarea form-input" id="detail-learnings" rows="3" placeholder="Capture learnings from this session..." onblur="window.saveLearnings(\'' + sessionId + '\')">' + (s.learnings || '') + '</textarea>';
610	            html += '</div>';
611	
612	            // Continue session (for terminal sessions)
613	            if (['succeeded', 'failed', 'timeout'].indexOf(s.status) >= 0) {
