    def _handle_get_projects(self) -> None:
        projects_dir = REPO_ROOT / "projects"
        result = []
        if projects_dir.exists():
            for p in sorted(projects_dir.iterdir()):
                pj = p / "project.json"
                if pj.exists():
                    try:
                        data = json.loads(pj.read_text(encoding="utf-8"))
