        limit = int(params.get("limit", "50"))
        event_type = params.get("type", "")
        since = params.get("since", "")

        history = events.get_history(
            limit=limit,
            event_type=event_type or None,
            since=since or None,
        )
        self._send_json({"events": history, "total": len(history)})

